// Presentation-only preview: separate DOM, never a transaction or an action target.
function renderColorPreview(content) {
  let preview=document.getElementById('recordColorPreview');
  if(parent.V2RecordPreview!==true){preview?.remove();return;}
  if(!preview){preview=document.createElement('section');preview.id='recordColorPreview';preview.setAttribute('aria-label','标签配色示例，不是真实交易');content.append(preview);}
  const examples=[
    ['买入','buy','已同步','status-done','¥100.00'],
    ['卖出','sell','同步失败','status-error','10.00 份'],
    ['定投','invest','等待正式净值','status-waiting','¥5.00'],
    ['分红','dividend','已同步','status-done','¥10.00'],
    ['调整','adjust','持仓发生变化','status-warning','100.00 份'],
    ['初始持仓','initial','已导入','status-done','100.00 份']
  ].filter(row=>filter==='全部'||row[0]===filter);
  preview.hidden=!examples.length;
  preview.innerHTML='<div class="date-heading"><span class="date-main">配色示例</span></div><p class="preview-notice">仅供查看，不是真实交易，不能操作</p>'+examples.map(([type,cls,status,state,value])=>'<div class="record-preview-card"><div class="card"><div class="card-top"><div class="fund-wrap"><span class="fund-name">'+type+'示例</span></div><div class="value-wrap"><span class="amount neutral">'+value+'</span></div></div><div class="meta-row"><span class="tag type-'+cls+'">'+type+'</span><span class="tag '+state+'">'+status+'</span></div></div></div>').join('');
}
